package datamodel

// Characterization pins: what the data model's engine-dependent rules give
// today, for each engine and for an ID no build knows. Each test reaches
// its rule through one local closure; when a switch moves into a
// per-engine method (TypeKindOf, TypeOfKind and the like), re-point that
// closure and leave the pinned values alone. A value printed as
// "unpinned" is one the table lacks.

import (
	"fmt"
	"strings"
	"testing"

	"dgopher/internal/db"
)

var pinEngines = []db.Engine{db.Postgres, db.MySQL, db.ClickHouse, db.SQLite, db.DuckDB, db.Redis, "unknown"}

var modelEngines = []db.Engine{db.Postgres, db.MySQL, db.ClickHouse, db.SQLite, db.DuckDB}

// pinValues checks the values produce gives against want, by key: each
// key given must be pinned with the same value, and each pinned key given.
func pinValues(t *testing.T, name string, want map[string]string, produce func(add func(key, got string))) {
	t.Helper()
	seen := map[string]bool{}
	produce(func(key, got string) {
		t.Helper()
		if seen[key] {
			t.Fatalf("%s: key %q given twice", name, key)
		}
		seen[key] = true
		w, ok := want[key]
		switch {
		case !ok:
			t.Errorf("unpinned %s: %q: %q,", name, key, got)
		case got != w:
			t.Errorf("%s %s changed:\n got  %q\n want %q", name, key, got, w)
		}
	})
	for key := range want {
		if !seen[key] {
			t.Errorf("%s: %q is pinned but no longer given", name, key)
		}
	}
}

// pinTypes are column types of every engine's spelling.
var pinTypes = []string{
	"smallint", "smallint unsigned", "int", "int unsigned", "integer", "mediumint", "bigint", "bigint unsigned", "serial",
	"tinyint(1)", "tinyint", "numeric(12,2)", "decimal", "real", "double precision", "float8", "boolean",
	"varchar(40)", "character varying", "char(3)", "nvarchar(10)", "text", "longtext", "date", "time", "timetz",
	"timestamp", "timestamp with time zone", "datetime", "uuid", "jsonb", "bytea", "longblob", "text[]", "interval",
	"Int8", "UInt16", "UInt32", "UInt64", "Decimal(18, 4)", "Float32", "Bool", "String", "FixedString(4)", "Date32",
	"DateTime", "DateTime64(3, 'UTC')", "Nullable(Int32)", "LowCardinality(String)", "Array(Int32)",
}

