// When a model compares two types as one.
func TestPinSameType(t *testing.T) {
	pairs := [][2]string{
		{"varchar(20)", "character varying(20)"}, {"varchar(20)", "varchar(30)"}, {"varchar", "text"}, {"tinyint(1)", "boolean"},
		{"int", "integer"}, {"int unsigned", "int"}, {"VARCHAR", "VARCHAR(10)"}, {"Nullable(Int32)", "Int32"}, {"numeric(10,2)", "decimal(10,2)"},
	}
	pinValues(t, "same type", map[string]string{
		"postgres":   "varchar(20) = character varying(20): true\nvarchar(20) = varchar(30): false\nvarchar = text: false\ntinyint(1) = boolean: false\nint = integer: true\nint unsigned = int: false\nVARCHAR = VARCHAR(10): false\nNullable(Int32) = Int32: false\nnumeric(10,2) = decimal(10,2): true",
		"mysql":      "varchar(20) = character varying(20): true\nvarchar(20) = varchar(30): false\nvarchar = text: false\ntinyint(1) = boolean: true\nint = integer: true\nint unsigned = int: false\nVARCHAR = VARCHAR(10): false\nNullable(Int32) = Int32: false\nnumeric(10,2) = decimal(10,2): true",
		"clickhouse": "varchar(20) = character varying(20): false\nvarchar(20) = varchar(30): false\nvarchar = text: false\ntinyint(1) = boolean: false\nint = integer: false\nint unsigned = int: false\nVARCHAR = VARCHAR(10): false\nNullable(Int32) = Int32: true\nnumeric(10,2) = decimal(10,2): false",
		"sqlite":     "varchar(20) = character varying(20): true\nvarchar(20) = varchar(30): false\nvarchar = text: false\ntinyint(1) = boolean: false\nint = integer: true\nint unsigned = int: false\nVARCHAR = VARCHAR(10): false\nNullable(Int32) = Int32: false\nnumeric(10,2) = decimal(10,2): true",
		"duckdb":     "varchar(20) = character varying(20): true\nvarchar(20) = varchar(30): true\nvarchar = text: false\ntinyint(1) = boolean: false\nint = integer: true\nint unsigned = int: false\nVARCHAR = VARCHAR(10): true\nNullable(Int32) = Int32: false\nnumeric(10,2) = decimal(10,2): true",
		"redis":      "varchar(20) = character varying(20): true\nvarchar(20) = varchar(30): false\nvarchar = text: false\ntinyint(1) = boolean: false\nint = integer: true\nint unsigned = int: false\nVARCHAR = VARCHAR(10): false\nNullable(Int32) = Int32: false\nnumeric(10,2) = decimal(10,2): true",
		"unknown":    "varchar(20) = character varying(20): true\nvarchar(20) = varchar(30): false\nvarchar = text: false\ntinyint(1) = boolean: false\nint = integer: true\nint unsigned = int: false\nVARCHAR = VARCHAR(10): false\nNullable(Int32) = Int32: false\nnumeric(10,2) = decimal(10,2): true",
	}, func(add func(key, got string)) {
		for _, e := range pinEngines {
			var lines []string
			for _, p := range pairs {
				lines = append(lines, fmt.Sprintf("%s = %s: %v", p[0], p[1], sameType(e, p[0], p[1])))
			}
			add(string(e), strings.Join(lines, "\n"))
		}
	})
}

